(()=>{
'use strict';
const root=document.getElementById('hub-main');
const connectivity=document.getElementById('hub-connectivity');
const cfg=window.TITAN_HUB||{};
const base=`/customer/${encodeURIComponent(cfg.portal)}/api`;
const nav=[...document.querySelectorAll('[data-workspace]')];
let current='home';

const el=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined&&text!==null)node.textContent=String(text);return node;};
const valueText=value=>{if(value===null||value===undefined)return '—';if(typeof value==='boolean')return value?'Yes':'No';if(typeof value==='object')return Object.entries(value).map(([k,v])=>`${k}: ${valueText(v)}`).join(' · ');return String(value);};
const listItems=props=>Array.isArray(props?.items)?props.items:[];

function card(title,subtitle){const section=el('section','card');if(title)section.append(el('h2','card-title',title));if(subtitle)section.append(el('p','muted',subtitle));return section;}
function entityCard(item){const section=el('article','entity-card');if(item&&typeof item==='object'){const title=item.name??item.title??item.reference??item.id??'Item';section.append(el('h3','entity-title',title));for(const [key,value] of Object.entries(item)){if(['name','title','reference','id'].includes(key)||typeof value==='object')continue;const row=el('div','entity-row');row.append(el('span','entity-key',key.replaceAll('_',' ')),el('span','entity-value',valueText(value)));section.append(row);}}else section.append(el('p','',valueText(item)));return section;}
function dataList(props){const section=card(props?.title);const items=listItems(props);if(items.length===0){section.append(el('p','muted',props?.empty_message||'Nothing to show.'));return section;}const list=el('div','data-list');items.forEach(item=>list.append(entityCard(item)));section.append(list);return section;}
function keyValueList(props){const section=card();for(const item of listItems(props)){const row=el('div','kv-row');row.append(el('span','kv-key',item?.label??'Item'),el('span','kv-value',valueText(item?.value)));section.append(row);}return section;}
function summaryBanner(props){const section=el('section','summary-banner');section.append(el('h1','summary-title',props?.title||'Titan Hub'));if(props?.subtitle)section.append(el('p','muted',props.subtitle));return section;}
function emptyState(props){const section=card(props?.title||'Nothing here');section.append(el('p','muted',props?.message||props?.empty_message||'There is nothing to show yet.'));return section;}
function chatThread(props){const section=card();const items=listItems(props);if(items.length===0)return emptyState({title:'Inbox',message:props?.empty_message||'No messages yet.'});for(const item of items){const message=el('article','chat-message');if(item&&typeof item==='object'){message.append(el('strong','',item.sender_name??item.sender??'Update'));message.append(el('p','',item.message??item.text??item.summary??valueText(item)));}else message.append(el('p','',valueText(item)));section.append(message);}return section;}
function actionBar(props){const section=el('section','action-bar');for(const action of Array.isArray(props?.actions)?props.actions:[]){if(!action||typeof action.intent!=='string'||!action.intent.startsWith('hub.'))continue;const button=el('button','action-button',action.label||'Continue');button.type='button';button.dataset.intent=action.intent;button.addEventListener('click',()=>dispatchIntent(action.intent,{}));section.append(button);}return section;}
function genericNode(node){const section=card(node?.component||'Content');const props=node?.props&&typeof node.props==='object'?node.props:{};for(const [key,value] of Object.entries(props)){if(typeof value==='object')continue;const row=el('div','kv-row');row.append(el('span','kv-key',key.replaceAll('_',' ')),el('span','kv-value',valueText(value)));section.append(row);}return section;}
function renderNode(node){if(!node||typeof node!=='object')return emptyState({message:'Presentation unavailable.'});const props=node.props||{};let out;switch(node.component){case'mobile-app-shell':out=el('div','workspace-shell');break;case'summary-banner':out=summaryBanner(props);break;case'data-list':out=dataList(props);break;case'entity-card':out=entityCard(props);break;case'empty-state':out=emptyState(props);break;case'chat-thread':out=chatThread(props);break;case'key-value-list':out=keyValueList(props);break;case'action-bar':out=actionBar(props);break;case'network-status':out=card(props?.title||'Connection',props?.message);break;default:out=genericNode(node);}for(const child of Array.isArray(node.children)?node.children:[])out.append(renderNode(child));return out;}
function setConnectivity(){const online=navigator.onLine;if(connectivity){connectivity.textContent=online?'Online':'Offline';connectivity.dataset.state=online?'online':'offline';}document.body.dataset.connectivity=online?'online':'offline';}
function showLoading(name){root.replaceChildren(card(name[0].toUpperCase()+name.slice(1),'Loading your workspace…'));root.setAttribute('aria-busy','true');}
function showOffline(name){const section=emptyState({title:name[0].toUpperCase()+name.slice(1),message:'This workspace needs a connection. Your Hub shell remains available and private business data is not stored offline.'});section.prepend(el('div','network-status','Offline'));root.replaceChildren(section);}
async function load(name){current=name;showLoading(name);try{const r=await fetch(`${base}/interface/${encodeURIComponent(name)}`,{credentials:'same-origin',headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const payload=await r.json();const data=payload?.data||{};const tree=data.tree||data;if(!tree||typeof tree!=='object')throw new Error('Invalid presentation');root.replaceChildren(renderNode(tree));}catch(error){if(!navigator.onLine)showOffline(name);else root.replaceChildren(emptyState({title:'Unable to load workspace',message:'Titan Hub could not load this workspace. Please try again.'}));}finally{root.removeAttribute('aria-busy');}}
async function dispatchIntent(intent,payload){try{const r=await fetch(`${base}/interact`,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({intent,input:{payload}})});if(!r.ok)throw new Error(`HTTP ${r.status}`);await load(current);}catch(error){root.prepend(emptyState({title:'Action unavailable',message:'The request could not be sent. No business action was performed.'}));}}
async function loadCapabilities(){try{const r=await fetch(`${base}/capabilities`,{credentials:'same-origin',headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)return;const workspaces=(await r.json())?.data?.workspaces||{};nav.forEach(button=>{const name=button.dataset.workspace||'home';const available=workspaces?.[name]?.available!==false;button.disabled=!available;button.setAttribute('aria-disabled',available?'false':'true');if(!available)button.title='Unavailable for this account';});}catch(_error){/* capability discovery is advisory; workspace requests still fail closed */}}
nav.forEach(button=>button.addEventListener('click',()=>{if(button.disabled)return;nav.forEach(x=>x.setAttribute('aria-current','false'));button.setAttribute('aria-current','true');load(button.dataset.workspace||'home');}));
window.addEventListener('offline',()=>{setConnectivity();showOffline(current);});
window.addEventListener('online',()=>{setConnectivity();load(current);});
setConnectivity();loadCapabilities();load('home');
})();
